import {validate} from './engine.js';
export function encodeRules(rules){const error=validate(rules);if(error)throw Error(error);const bytes=new TextEncoder().encode(JSON.stringify({v:1,rules}));let binary='';for(const b of bytes)binary+=String.fromCharCode(b);return btoa(binary).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'');}
export function decodeRules(encoded){if(encoded.length>200000)throw Error('共有URLが長すぎます。CSV を使用してください。');const binary=atob(encoded.replaceAll('-','+').replaceAll('_','/'));const data=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(binary,c=>c.charCodeAt(0))));if(data.v!==1||!Array.isArray(data.rules)||data.rules.some(r=>!Array.isArray(r)||r.some(v=>typeof v!=='string')))throw Error('共有URLの形式が正しくありません。');const error=validate(data.rules);if(error)throw Error(error);return data.rules;}
